"""ACME pre-network diagnostic in the exact service sandbox. Closed exit/line only."""
import os,json,subprocess
from pathlib import Path
SCRIPT='#!/nix/store/rzl7zd3zx56vl7m55x1l49sr4xx2bb7y-bash-5.3p9/bin/bash\nset -e\n\nset -euo pipefail\numask 0077\n# No contact, account key, registration or ACME output enters journald.\nexec >/dev/null 2>&1\nexec 3>/run/mrjam-acme/vise-diagnostic-001.json\ntrap \'printf "{\\"line\\":%s,\\"exit\\":%s}\\n" "$LINENO" "$?" >&3\' EXIT\nexec 9>/run/mrjam-acme/renew.lock\nflock -x 9\ntest -d accounts\ntest ! -L accounts\ntest -d certificates\ntest ! -L certificates\ntest -d out\ntest ! -L out\n# Select exactly one existing account. A missing/ambiguous account fails\n# before network access. Contact stays in this private process environment.\nmapfile -d "" account_keys < <(find -P accounts -type f -name \'*.key\' -print0)\ntest "${#account_keys[@]}" -eq 1\naccount_key="${account_keys[0]}"\ntest -s "$account_key"\ntest ! -L "$account_key"\nexport LEGO_EMAIL="${account_key##*/}"\nexport LEGO_EMAIL="${LEGO_EMAIL%.key}"\ntest -n "$LEGO_EMAIL"\ncase "$LEGO_EMAIL" in *$\'\\n\'*|*$\'\\r\'*|*\'/\'*) exit 1;; esac\n# Match lego\'s exact layout before it can look up a different identity.\naccount_user="accounts/acme-v02.api.letsencrypt.org/$LEGO_EMAIL"\ntest "$account_key" = "$account_user/keys/$LEGO_EMAIL.key"\nfor directory in accounts/acme-v02.api.letsencrypt.org "$account_user" "$account_user/keys"; do\n  test -d "$directory"\n  test ! -L "$directory"\ndone\nregistration="$account_user/account.json"\ntest -s "$registration"\ntest ! -L "$registration"\nfor extension in crt key json issuer.crt; do\n  file="certificates/vise.mrj.am.$extension"\n  test -s "$file"\n  test ! -L "$file"\ndone\n# There is deliberately no lego run/register fallback and no self-signed\n# certificate path. Missing state cannot create a new account or cert.\nexit 0\n'
UNIT='[Unit]\nAfter=network-online.target nginx.service mrjam-acme-runtime.service\nAssertPathExists=/var/lib/acme/vise.mrj.am/fullchain.pem\nAssertPathExists=/var/lib/acme/vise.mrj.am/key.pem\nAssertPathIsDirectory=/var/lib/acme/.lego/accounts/a96772ab152e39f749f9\nAssertPathIsDirectory=/var/lib/acme/.lego/vise.mrj.am/748661661a99cbbf91d5\nAssertPathIsDirectory=/var/lib/acme/vise.mrj.am\nAssertPathIsDirectory=/var/lib/acme/acme-challenge\nDescription=Renew existing ACME certificate vise.mrj.am with its retained account\nRequires=nginx.service mrjam-acme-runtime.service\nWants=network-online.target\n\n[Service]\nEnvironment="LOCALE_ARCHIVE=/nix/store/41b4nygazaawgbags71flx463x4426kf-glibc-locales-2.42-67/lib/locale/locale-archive"\nEnvironment="PATH=/nix/store/gph17gb73p6qbrqqjnypfjj5npf0ldyx-coreutils-9.11/bin:/nix/store/jwq26byp7q4mxqg3yqqq4vgsabs7yknm-findutils-4.10.0/bin:/nix/store/4n075ll5jdwbjv142yg8ymz5f3yf4pam-util-linux-2.42.2-bin/bin:/nix/store/gqv7phqvmll7dprdmya6102ph64wvj0h-openssl-3.6.3-bin/bin:/nix/store/98mjbvzc0k4k5qq7i11920ah7qg66dqx-lego-4.35.2/bin:/nix/store/gph17gb73p6qbrqqjnypfjj5npf0ldyx-coreutils-9.11/bin:/nix/store/jwq26byp7q4mxqg3yqqq4vgsabs7yknm-findutils-4.10.0/bin:/nix/store/sacz532zgiacvg7mva9v6gbfmyw427i3-gnugrep-3.12/bin:/nix/store/svl89366pvzz5s3myh1fjniz9l0x17fh-gnused-4.10/bin:/nix/store/0xiinbh7pbj479i5v28mqnjrvhvbdibf-systemd-260.2/bin:/nix/store/gph17gb73p6qbrqqjnypfjj5npf0ldyx-coreutils-9.11/sbin:/nix/store/jwq26byp7q4mxqg3yqqq4vgsabs7yknm-findutils-4.10.0/sbin:/nix/store/4n075ll5jdwbjv142yg8ymz5f3yf4pam-util-linux-2.42.2-bin/sbin:/nix/store/gqv7phqvmll7dprdmya6102ph64wvj0h-openssl-3.6.3-bin/sbin:/nix/store/98mjbvzc0k4k5qq7i11920ah7qg66dqx-lego-4.35.2/sbin:/nix/store/gph17gb73p6qbrqqjnypfjj5npf0ldyx-coreutils-9.11/sbin:/nix/store/jwq26byp7q4mxqg3yqqq4vgsabs7yknm-findutils-4.10.0/sbin:/nix/store/sacz532zgiacvg7mva9v6gbfmyw427i3-gnugrep-3.12/sbin:/nix/store/svl89366pvzz5s3myh1fjniz9l0x17fh-gnused-4.10/sbin:/nix/store/0xiinbh7pbj479i5v28mqnjrvhvbdibf-systemd-260.2/sbin"\nEnvironment="TZDIR=/nix/store/m2sv1rizzbnsb35hv3ii0dnf3rvfy3n3-tzdata-2026c/share/zoneinfo"\nX-RestartIfChanged=false\nX-StopIfChanged=false\nAmbientCapabilities=\nBindPaths=/var/lib/acme/.lego/vise.mrj.am/748661661a99cbbf91d5:/tmp/certificates\nBindPaths=/var/lib/acme/vise.mrj.am:/tmp/out\nBindReadOnlyPaths=/var/lib/acme/.lego/accounts/a96772ab152e39f749f9:/tmp/accounts\nCPUQuota=25%\nCapabilityBoundingSet=\nExecStart=/run/mrjam-acme/vise-diagnostic-001.sh\nGroup=nginx\nLockPersonality=true\nMemoryDenyWriteExecute=true\nMemoryMax=256M\nNoNewPrivileges=true\nPrivateDevices=true\nPrivateTmp=true\nProcSubset=pid\nProtectClock=true\nProtectControlGroups=true\nProtectHome=true\nProtectHostname=true\nProtectKernelLogs=true\nProtectKernelModules=true\nProtectKernelTunables=true\nProtectProc=invisible\nProtectSystem=strict\nReadWritePaths=/var/lib/acme/.lego/vise.mrj.am/748661661a99cbbf91d5\nReadWritePaths=/var/lib/acme/vise.mrj.am\nReadWritePaths=/var/lib/acme/acme-challenge\nReadWritePaths=/run/mrjam-acme\nRestrictAddressFamilies=AF_UNIX\nRestrictAddressFamilies=AF_INET\nRestrictAddressFamilies=AF_INET6\nRestrictNamespaces=true\nRestrictRealtime=true\nRestrictSUIDSGID=true\nStandardError=null\nStandardOutput=null\nTasksMax=64\nTimeoutStartSec=30min\nType=oneshot\nUMask=0077\nUser=acme\nWorkingDirectory=/tmp\n'
S='/nix/store/0xiinbh7pbj479i5v28mqnjrvhvbdibf-systemd-260.2/bin/systemctl'
assert os.geteuid()==0 and os.uname().nodename=='srv1982677'
name='mrjam-vise-acme-diagnostic-001.service'
p=Path('/run/systemd/system')/name
script=Path('/run/mrjam-acme/vise-diagnostic-001.sh')
assert not p.exists() and not script.exists()
os.umask(0o077)
with script.open('x') as f:f.write(SCRIPT)
os.chmod(script,0o555)
with p.open('x') as f:f.write(UNIT)
try:
 subprocess.run([S,'daemon-reload'],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=60)
 r=subprocess.run([S,'start',name],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=60)
 result=json.loads(Path('/run/mrjam-acme/vise-diagnostic-001.json').read_text())
 assert set(result)=={'line','exit'} and all(type(v) is int for v in result.values())
 print(json.dumps({'code':'VISE_ACME_PREFIX_DIAGNOSIS','result':result,'service_exit':r.returncode}))
finally:
 subprocess.run([S,'stop',name],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=30)
 assert p.read_text()==UNIT and script.read_text()==SCRIPT
 p.unlink();script.unlink()
 subprocess.run([S,'daemon-reload'],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=60)
